head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF05700";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — comAttrTpCdList, transstkAgntCdList

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_100", fn: function(){ return ((((dma_map.get("foundDd") ?? (() => { throw new Error("unresolved:" + "map.foundDd"); })())) && typeof ((dma_map.get("foundDd") ?? (() => { throw new Error("unresolved:" + "map.foundDd"); })())).getRowCount === 'function' ? ((dma_map.get("foundDd") ?? (() => { throw new Error("unresolved:" + "map.foundDd"); })())).getRowCount() : ((((dma_map.get("foundDd") ?? (() => { throw new Error("unresolved:" + "map.foundDd"); })())) == null) ? 0 : (((dma_map.get("foundDd") ?? (() => { throw new Error("unresolved:" + "map.foundDd"); })())).length || 0))) === 8); } }, { id: "if_comAttrTpCd_txt", fn: function(){ return ((dma_map.get("comAttrTpCd") ?? (() => { throw new Error("unresolved:" + "map.comAttrTpCd"); })()) === (() => { throw new Error("unresolved:data:" + "row.cdVal"); })()); } }, { id: "if_cdVal", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cdVal"); })() === '1'); } }, { id: "if_comAttrTpCd_2_txt", fn: function(){ return ((dma_map.get("comAttrTpCd") ?? (() => { throw new Error("unresolved:" + "map.comAttrTpCd"); })()) === (() => { throw new Error("unresolved:data:" + "row.cdVal"); })()); } }, { id: "if_cdVal_2", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cdVal"); })() === '2'); } }, { id: "if_comAttrTpCd_3_txt", fn: function(){ return ((dma_map.get("comAttrTpCd") ?? (() => { throw new Error("unresolved:" + "map.comAttrTpCd"); })()) === (() => { throw new Error("unresolved:data:" + "row.cdVal"); })()); } }, { id: "if_cdVal_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cdVal"); })() !== '1' && (() => { throw new Error("unresolved:data:" + "row.cdVal"); })() !== '2'); } }, { id: "c_when_112", fn: function(){ return (!(String(((dma_pageContext.get("comAttrTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("comAttrTpCdList") ?? ""))).length === 0)); } }, { id: "txt_label138", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cdVal"); })() !== '0'); } }, { id: "c_when_135", fn: function(){ return (!(String(((dma_pageContext.get("transstkAgntCdList") ?? "")) == null ? '' : ((dma_pageContext.get("transstkAgntCdList") ?? ""))).length === 0)); } }, { id: "txt_strong156", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'Y'); } }, { id: "if_listStatCd_2", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) !== 'Y'); } }, { id: "txt_strong156", fn: function(){ return ((dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '1' || (dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '2' || (dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '6'); } }, { id: "if_listStatCd_2", fn: function(){ return ((dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '1' || (dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '2' || (dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '6'); } }, { id: "c_otherwise_160", fn: function(){ return (!(((dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '1' || (dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '2' || (dma_map.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "map.spotIsuTrdMktTpCd"); })()) === '6'))); } }, { id: "if_activYn", fn: function(){ return ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) === 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_113", entity: "dlt_comAttrTpCdList", countIds: [], cells: [{ childId: "__rc16", fn: function (v, i) { return String(v("cdValNm")); } }] },
        { genId: "c_foreach_136", entity: "dlt_transstkAgntCdList", countIds: [], cells: [{ childId: "__rc20", fn: function (v, i) { return String(v("cdValNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb10", fn: function () { return String(dma_map.get("zipcd")) + " " + String(dma_map.get("addr")) + " " + String(dma_map.get("dtlAddr")); } },
        { childId: "__rb11", fn: function () { return String(dma_map.get("engAddr")) + " " + String(dma_map.get("engDtlAddr")); } },
        { childId: "__rb13", fn: function () { return "http://" + String(dma_map.get("hpage")); } },
        { childId: "__rb14", fn: function () { return String(dma_map.get("corpTelNo")) + " " + String(dma_map.get("telNo")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldinf05700: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":2
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05700' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf05700.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_menuLink_onclick
 * @description btn_menuLink 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_menuLink_onclick = function(e){
    try {
        menuLink(05400)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05700.btn_menuLink_onclick' }); }
};

/**
 * @method
 * @name btn_menuLink_2_onclick
 * @description btn_menuLink_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_menuLink_2_onclick = function(e){
    try {
        menuLink(05400)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05700.btn_menuLink_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
